using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1StoryWalk {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-13_1F_EnvironmentalStory/";const float cell=.30f,x0=-69,z0=-40;const int nx=398,nz=251;static bool[] valid;static float[] heights;
 static Vector3 Pos(int i)=>new Vector3(x0+(i%nx)*cell,heights[i],z0+(i/nx)*cell);
 static bool Free(Vector3 p,out float y){y=0;if(!Physics.Raycast(p+Vector3.up*.5f,Vector3.down,out var h,1.45f,~0,QueryTriggerInteraction.Ignore)||h.point.y<-.8f||h.point.y>.2f)return false;y=h.point.y;return !Physics.CheckCapsule(new Vector3(p.x,y+.43f,p.z),new Vector3(p.x,y+1.50f,p.z),.33f,~0,QueryTriggerInteraction.Ignore);}
 static int Near(Vector3 p,float max=1.0f){int best=-1;float d=max*max;int xx=Mathf.RoundToInt((p.x-x0)/cell),zz=Mathf.RoundToInt((p.z-z0)/cell),radius=Mathf.CeilToInt(max/cell);for(int z=zz-radius;z<=zz+radius;z++)for(int x=xx-radius;x<=xx+radius;x++){if(x<0||x>=nx||z<0||z>=nz)continue;int i=z*nx+x;if(!valid[i])continue;float ds=(Pos(i)-p).sqrMagnitude;if(ds<d){best=i;d=ds;}}return best;}
 static List<Vector3> Route(int start,int end){if(start<0||end<0)return null;var prev=Enumerable.Repeat(-1,nx*nz).ToArray();var queue=new Queue<int>();queue.Enqueue(start);prev[start]=start;while(queue.Count>0&&prev[end]<0){int cur=queue.Dequeue(),x=cur%nx,z=cur/nx;foreach(int to in new[]{cur-1,cur+1,cur-nx,cur+nx}){if(to<0||to>=prev.Length||Mathf.Abs(to%nx-x)>1||!valid[to]||prev[to]>=0)continue;prev[to]=cur;queue.Enqueue(to);}}if(prev[end]<0)return null;var raw=new List<Vector3>();for(int at=end;;at=prev[at]){raw.Add(Pos(at));if(at==start)break;}raw.Reverse();var route=new List<Vector3>();for(int i=0;i<raw.Count;i++)if(i==0||i==raw.Count-1||Vector3.Cross(raw[i]-raw[i-1],raw[i+1]-raw[i]).sqrMagnitude>.0001f)route.Add(raw[i]);return route;}
 static object Travel(CharacterController cc,GameObject player,string id,List<Vector3> route){cc.enabled=false;player.transform.position=route[0]+Vector3.up*(cc.height*.5f-cc.center.y+.025f);cc.enabled=true;Physics.SyncTransforms();int steps=0,segment=0;float remaining=0;bool pass=true;Vector3 target=route[0];foreach(var to in route.Skip(1)){target=to;segment++;int limit=Mathf.CeilToInt(Vector3.Distance(player.transform.position,to)/.09f)+65;for(int i=0;i<limit;i++){var d=to-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.04f)break;cc.Move(d.normalized*Mathf.Min(.09f,remaining)+Vector3.down*.065f);steps++;}if(remaining>.12f){pass=false;break;}}for(int i=0;i<10;i++)cc.Move(Vector3.down*.04f);float bottom=player.transform.position.y+cc.center.y-cc.height*.5f;float err=bottom-target.y;if(Mathf.Abs(err)>.20f)pass=false;cc.enabled=false;return new{id,passed=pass,steps,segment,remaining,heightError=err,end=new[]{player.transform.position.x,bottom,player.transform.position.z}};}
 public static object Extra(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var results=new List<object>();try{cc.enabled=false;Physics.SyncTransforms();var stair=new List<Vector3>{new Vector3(-24.65f,0,-10.7f)};for(int i=0;i<20;i++)stair.Add(new Vector3(-24.65f,(i+1)*.17f,-10.1f+(i+.5f)*.31f));stair.Add(new Vector3(-24.65f,3.465f,-3.8f));stair.Add(new Vector3(-24.65f,3.465f,8));results.Add(Travel(cc,player,"catwalk_up",stair));stair.Reverse();results.Add(Travel(cc,player,"catwalk_down",stair));
   var road=new List<Vector3>();for(float x=-51;x>=-95;x-=.5f){float z=-28-.035f*Mathf.Max(0,-51-x);Physics.Raycast(new Vector3(x,2,z),Vector3.down,out var hit,5,~0,QueryTriggerInteraction.Ignore);road.Add(new Vector3(x,hit.point.y,z));}results.Add(Travel(cc,player,"outside_road",road));road.Reverse();results.Add(Travel(cc,player,"outside_road_return",road));}finally{EditorSceneManager.OpenScene(s.path);}var result=new{tested=results.Count,failed=results.Count(v=>!(bool)v.GetType().GetProperty("passed").GetValue(v)),results};File.WriteAllText(O+"walk_extra.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");var p=JObject.Parse(File.ReadAllText(R+"/SourceAssets/F1_AbandonedCamouflage/before_layout.json"));var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var old=player.transform.position;bool enabled=cc.enabled;var results=new List<object>();var paths=new List<object>();var fails=new List<string>();valid=new bool[nx*nz];heights=new float[nx*nz];cc.enabled=false;Physics.SyncTransforms();
  void Test(string id,Vector3 a,Vector3 b,bool reverse=false){int start=Near(a,.65f),end=Near(b,.8f);var route=Route(start,end);if(route==null){fails.Add(id+" unreachable start="+start+" end="+end);return;}paths.Add(new{id,points=route.Select(v=>new[]{v.x,v.y,v.z}).ToArray()});results.Add(Travel(cc,player,id,route));if(reverse){route.Reverse();results.Add(Travel(cc,player,id+"_reverse",route));}}
  try{for(int i=0;i<valid.Length;i++){var v=new Vector3(x0+(i%nx)*cell,0,z0+(i/nx)*cell);valid[i]=Free(v,out heights[i]);}
   foreach(var t in p["tunnels"]){string a=(string)t["a"],b=(string)t["b"];var ra=p["rooms"].First(q=>(string)q["id"]==a);var da=ra["doors"].First(q=>(string)q["id"]==(string)t["id"]);Vector3 from=new Vector3((float)da["point"][0],0,(float)da["point"][2]);Vector3 to;if(b=="OUT")to=new Vector3(-51,0,-28);else{var rb=p["rooms"].First(q=>(string)q["id"]==b);var db=rb["doors"].First(q=>(string)q["id"]==(string)t["id"]);to=new Vector3((float)db["point"][0],0,(float)db["point"][2]);}Test((string)t["id"],from,to,true);}
   foreach(var r in p["rooms"]){string id=(string)r["id"];var d=r["doors"][0]["point"];Vector3 start=new Vector3((float)d[0],0,(float)d[2]);foreach(var door in r["doors"].Skip(1)){var pt=door["point"];Test(id+"_door_"+(string)door["id"],start,new Vector3((float)pt[0],0,(float)pt[2]),true);}
    foreach(var q in p["placements"].Where(q=>(string)q["room"]==id&&(bool)q["access"])){var g=GameObject.Find((string)q["name"]);if(!g)continue;var size=q["size"];var center=q["center"];var local=(string)q["model"]=="Forklift"?new Vector3(-1.25f,0,-.25f):new Vector3((float)center[0],0,(float)center[2]+(float)size[2]*.5f+.60f);var front=g.transform.TransformPoint(local);front.y=0;Test("work_"+g.name,start,front);}}
   foreach(var a in p["arrivals"]){var v=a["position"];Test((string)a["id"]+"_arrival_to_exterior",new Vector3((float)v[0],(float)v[1],(float)v[2]),new Vector3(-66,0,-28),true);}
  }finally{cc.enabled=false;player.transform.position=old;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}
  var result=new{results,planningFailures=fails,validCells=valid.Count(v=>v),tested=results.Count,failed=results.Count(v=>!(bool)v.GetType().GetProperty("passed").GetValue(v))};File.WriteAllText(O+"walk_floor.json",JsonConvert.SerializeObject(result,Formatting.Indented));File.WriteAllText(O+"routes_floor.json",JsonConvert.SerializeObject(paths,Formatting.Indented));return new{result.tested,result.failed,planningFailures=fails,result.validCells};
 }
}
